```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm;

struct Node;

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // `requires len(value.text) <= 4000` is the caller's obligation; we do
        // not depend on it for safety, but we never let the residual grow past
        // the output bound regardless.
        let text = message.text;

        // The one granted authority: ask the model for a label. We cannot act on
        // what it returns (no tool interface in this world); we can only read it.
        let system = "Classify this customer support message into exactly one of: \
                      billing_question, technical_support, account_change, \
                      general_inquiry, unknown. Reply with only that single label.";
        let label = inference_llm::infer(system, &text, "classify");

        // `ensures intent in [...]` holds by construction: Intent is a closed
        // enum, so adversarial text cannot widen the set. An unrecognised or
        // hostile label collapses to `unknown`.
        let intent = classify(&label);

        // The free-text residual: bounded to satisfy `ensures len(question) <= 512`
        // and still treated as adversarial downstream.
        let question = truncate_chars(&text, 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

fn classify(label: &str) -> Intent {
    let l = label.trim().to_ascii_lowercase();
    if l.contains("billing") {
        Intent::BillingQuestion
    } else if l.contains("technical") || l.contains("support") {
        Intent::TechnicalSupport
    } else if l.contains("account") {
        Intent::AccountChange
    } else if l.contains("general") || l.contains("inquiry") {
        Intent::GeneralInquiry
    } else {
        Intent::Unknown
    }
}

/// Keep at most `max` Unicode scalar values, so the result's character length is
/// bounded by `max` on a well-formed boundary and we never split a char.
fn truncate_chars(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

export!(Node);
```

